                throw GenerationException::planRequiresNonEmptyOutput($this->lexicalGrammar->version());
            }
            $this->coverage?->commitAttempt(
                hash('sha256', $sql),
                $this->lastSequence === null ? [] : (new SequenceObservation())->preserved($this->lastSequence)
            );
