$mysqlGenerator = SqlGeneratorFactory::forMySql($mysqlFaker, $mysqlGrammar, $mysqlVersion);
$mysqlFaker->seed(7);

$sql = $mysqlGenerator->generate(
    GenerationPlan::fromRule(\SqlFaker\MySql\StatementType::Select->value)
        ->requiringNonEmpty()
        ->withMaxDepth(3),
);
```

