$pgGenerator = SqlGeneratorFactory::forPostgreSql($pgFaker, $pgGrammar, $pgVersion);
$pgFaker->seed(7);

$sql = $pgGenerator->generate(
    GenerationPlan::fromRule(\SqlFaker\PostgreSql\StatementType::Select->value)
        ->requiringNonEmpty()
        ->withMaxDepth(3),
);

